package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.persistence;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.*;import com.yeyamo_mobile.api.moderation_trust_service.domain.port.ModerationReportRepository;
@Component public class JpaModerationReportAdapter implements ModerationReportRepository{private final SpringModerationReportRepository repo;public JpaModerationReportAdapter(SpringModerationReportRepository r){repo=r;}public ModerationReport save(ModerationReport r){return domain(repo.save(entity(r)));}public Optional<ModerationReport>findById(UUID id){return repo.findById(id).map(this::domain);}public List<ModerationReport>find(ReportStatus s,String reporter,int limit){var p=PageRequest.of(0,limit);List<ModerationReportEntity>v=reporter!=null?repo.findByReporterIdOrderByCreatedAtDesc(reporter,p):s!=null?repo.findByStatusOrderByCreatedAtDesc(s,p):repo.findAllByOrderByCreatedAtDesc(p);return v.stream().map(this::domain).toList();}public boolean existsOpen(TargetType t,String id,String reporter){return repo.existsByTargetTypeAndTargetIdAndReporterIdAndStatusIn(t,id,reporter,List.of(ReportStatus.OPEN,ReportStatus.REVIEW));}
 private ModerationReportEntity entity(ModerationReport r){var e=new ModerationReportEntity();e.setId(r.getId());e.setTargetType(r.getTargetType());e.setTargetId(r.getTargetId());e.setTargetOwnerId(r.getTargetOwnerId());e.setReporterId(r.getReporterId());e.setReason(r.getReason());e.setDetails(r.getDetails());e.setStatus(r.getStatus());e.setAssignedTo(r.getAssignedTo());e.setResolution(r.getResolution());e.setCreatedAt(r.getCreatedAt());e.setUpdatedAt(r.getUpdatedAt());e.setDecidedAt(r.getDecidedAt());e.setVersion(r.getVersion());return e;}private ModerationReport domain(ModerationReportEntity e){var r=new ModerationReport();r.setId(e.getId());r.setTargetType(e.getTargetType());r.setTargetId(e.getTargetId());r.setTargetOwnerId(e.getTargetOwnerId());r.setReporterId(e.getReporterId());r.setReason(e.getReason());r.setDetails(e.getDetails());r.setStatus(e.getStatus());r.setAssignedTo(e.getAssignedTo());r.setResolution(e.getResolution());r.setCreatedAt(e.getCreatedAt());r.setUpdatedAt(e.getUpdatedAt());r.setDecidedAt(e.getDecidedAt());r.setVersion(e.getVersion());return r;}}
